intentos.respuesta_cruda:
{
  "sql": "SELECT t.categoria_ingles, ROUND((t.flete_total / t.ingresos) * 100, 2) AS porcentaje_flete FROM ( SELECT COALESCE(t2.product_category_name_english, 'sin_categoria') AS categoria_ingles, SUM(oi.price) AS ingresos, SUM(oi.freight_value) AS flete_total FROM vw_ingresos_por_categoria t1 LEFT JOIN product_category_translation t2 ON t2.product_category_name = t1.categoria_ingles WHERE t1.ingresos >= 5000 GROUP BY categoria_ingles ) t ORDER BY porcentaje_flete DESC LIMIT 3"
}
